css:
/* Purpose stays green; paragraph ideas stay blue. */
.thesis.lit .key{background:var(--eff-bg);color:var(--eff-tx)}
.centre{background:var(--eff-bg);color:var(--eff-tx);border-color:var(--eff-tx)}
.centre span{color:var(--eff-tx)}
#introWhat{color:var(--eff-tx);background:var(--eff-bg)}
.build,.two{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.build.typing{grid-template-columns:200px minmax(0,1fr)}
.build>*{min-width:0;min-height:0}
.slot{grid-template-columns:132px minmax(0,1fr) 44px}
.two .slot{grid-template-columns:92px minmax(0,1fr)}
.two .slot>span:last-child{display:none}
.two .slot .box{min-width:0}
@media screen and (max-height:800px){
  .slide{padding:42px 36px 64px}
  h2{font-size:24px;margin-bottom:12px}
  .keyrow{margin-bottom:10px}
  .slot .box{font-size:18px;line-height:1.55}
  .worked{padding:12px 16px}
  .worked p{font-size:18px;line-height:1.5;margin-bottom:8px}
  .worked p:last-child{margin-bottom:0}
}
@media screen and (max-width:800px){
  .slide{padding-left:16px;padding-right:16px}
  .build,.build.typing{grid-template-columns:1fr;overflow:auto}
  .anchor{display:none}
  .two{grid-template-columns:1fr;overflow:auto}
  .two>div{min-height:380px}
  .slot,.two .slot{grid-template-columns:62px minmax(0,1fr)}
  .slot .sug{grid-column:1;grid-row:auto;margin:0}
  .slot .d{font-size:11px}
  .nav .now{min-width:0;font-size:11px}
}
